S = "Hakeem Force Academy"
QS = [
 (S, "A train covers 100 km in 1 hour. How much distance will it cover in 12 minutes at the same speed?", ["10 km", "20 km", "25 km", "12 km"], 1,
  "12 minutes is 12/60 = 1/5 of an hour. Distance = 100 x 1/5 = 20 km.", "Speed in km per hour times time in hours gives distance in km.", [1335]),
 (S, "How many inches are equal to 100 meters (to the nearest whole number)?", ["3281", "3937", "3600", "4000"], 1,
  "1 meter is about 39.37 inches. So 100 meters = 100 x 39.37 = 3937 inches.", "1 inch is exactly 2.54 centimeters.", [1724]),
 (S, "What is 0.001 x 100?", ["0.01", "1", "0.1", "0.0001"], 2,
  "Multiplying by 100 moves the decimal point two places to the right: 0.001 becomes 0.1.", "Multiplying by 10 moves the decimal point one place to the right.", [2607]),
 (S, "What is 0.01 x 100?", ["0.1", "10", "0.001", "1"], 3,
  "Multiplying by 100 moves the decimal point two places to the right: 0.01 becomes 1.", "0.01 is the same as 1/100, so 0.01 x 100 = 1.", [893, 452]),
 (S, "Which number comes next in the series: 115, 55, 170, 65, 235, ?", ["75", "85", "65", "310"], 0,
  "There are two interleaved series. First: 115, 170, 235 (add 55, then 65). Second: 55, 65, 75 (add 10 each time), so the next term is 75.", "The first series continues 310 after 235 (add 75).", [126, 316, 3883]),
 (S, "If the 1st day of a month is Monday, what day will the 11th be?", ["Wednesday", "Friday", "Thursday", "Tuesday"], 2,
  "From the 1st to the 11th is 10 days. 10 divided by 7 leaves 3, so Monday + 3 = Thursday.", "A week has 7 days, so the same weekday repeats every 7 days.", [1895]),
 (S, "If the 1st day of a month is Friday, what day will the 11th be?", ["Monday", "Sunday", "Tuesday", "Saturday"], 0,
  "From the 1st to the 11th is 10 days. 10 divided by 7 leaves 3, so Friday + 3 = Monday.", "The 8th, 15th, 22nd and 29th also fall on Friday in this month.", [1896]),
 (S, "If the 1st day of a month is Sunday, what day will the 11th be?", ["Tuesday", "Thursday", "Wednesday", "Monday"], 2,
  "From the 1st to the 11th is 10 days. 10 divided by 7 leaves 3, so Sunday + 3 = Wednesday.", "The 8th, 15th and 22nd of this month are Sundays.", [1903]),
 (S, "In a class of 1500 students, 1300 are present. How many students are absent?", ["200", "20", "150", "300"], 0,
  "Absent students = 1500 - 1300 = 200.", "The percentage absent is 200/1500 x 100 = 13.33 percent.", [1933]),
 (S, "If the 14th day of a month is Sunday, what day will the 19th be?", ["Monday", "Thursday", "Friday", "Saturday"], 2,
  "From the 14th to the 19th is 5 days. Sunday + 5 days = Friday.", "The 7th, 21st and 28th of this month are also Sundays.", [258]),
 (S, "If the 1st day of a month is Sunday, what day will the 14th be?", ["Sunday", "Friday", "Monday", "Saturday"], 3,
  "From the 1st to the 14th is 13 days. 13 divided by 7 leaves 6, so Sunday + 6 = Saturday.", "The 14th is two weeks after the 1st minus one day, so it is the day before the 1st's weekday.", [397]),
 (S, "If the 1st day of a month is Monday, what days will the 12th and the 15th be?", ["Friday and Monday", "Thursday and Sunday", "Friday and Sunday", "Saturday and Tuesday"], 0,
  "12th: 11 days after Monday, 11 mod 7 = 4, so Friday. 15th: 14 days after Monday is exactly two weeks, so Monday.", "The 15th always has the same weekday as the 1st.", [1884]),
 (S, "If the 2nd day of a month is Monday, what day will the 17th be?", ["Monday", "Wednesday", "Tuesday", "Sunday"], 2,
  "From the 2nd to the 17th is 15 days. 15 divided by 7 leaves 1, so Monday + 1 = Tuesday.", "The 9th and 16th of this month are Mondays.", [395]),
 (S, "If the 2nd day of a month is Friday, what day will the 17th be?", ["Saturday", "Friday", "Sunday", "Thursday"], 0,
  "From the 2nd to the 17th is 15 days. 15 divided by 7 leaves 1, so Friday + 1 = Saturday.", "The 9th and 16th of this month are Fridays.", [1899]),
 (S, "If the 4th day of a month is Thursday, what day will the 18th be?", ["Friday", "Wednesday", "Thursday", "Saturday"], 2,
  "From the 4th to the 18th is 14 days, exactly two weeks, so the weekday is the same: Thursday.", "Dates that differ by 7, 14, 21 or 28 always share the same weekday.", [1906]),
 (S, "If the 19th day of a month is Sunday, what day will the 26th be?", ["Monday", "Sunday", "Saturday", "Tuesday"], 1,
  "From the 19th to the 26th is 7 days, exactly one week, so the weekday is the same: Sunday.", "Dates 7 days apart always fall on the same weekday.", [746]),
 (S, "Whom did the British hold mainly responsible for the War of Independence of 1857?", ["Hindus", "Sikhs", "Muslims", "Marathas"], 2,
  "The British blamed the Muslims for the 1857 uprising, since the Mughal emperor Bahadur Shah Zafar was its symbolic leader.", "After 1857 the British treated Muslims harshly and the Mughal rule formally ended.", [4449]),
 (S, "Which English letters are the 23rd, 18th, 22nd and 12th letters of the alphabet, in that order?", ["W, R, V, L", "X, Q, U, K", "W, S, V, M", "V, R, W, L"], 0,
  "Counting A=1: 23 is W, 18 is R, 22 is V and 12 is L.", "The English alphabet has 26 letters.", [2496]),
 (S, "Which session of the All India Muslim League passed the Lahore (Pakistan) Resolution on 23 March 1940?", ["25th session", "26th session", "28th session", "27th session"], 3,
  "The Lahore Resolution was passed at the 27th annual session of the All India Muslim League held at Minto Park, Lahore, in March 1940.", "Quaid-e-Azam presided over this session, held from 22 to 24 March 1940.", [2330, 4021]),
 (S, "Which political party was in power in the areas that became Pakistan at the time of independence in 1947 and led the movement for Pakistan?", ["Indian National Congress", "All India Muslim League", "Unionist Party", "Khaksar Tehrik"], 1,
  "The All India Muslim League led by Quaid-e-Azam formed the first government of Pakistan in 1947.", "Liaquat Ali Khan was the first Prime Minister from the Muslim League.", [3931]),
 (S, "On what date was the Objectives Resolution passed by the Constituent Assembly of Pakistan?", ["12 March 1949", "23 March 1949", "12 March 1948", "14 August 1949"], 0,
  "The Objectives Resolution was moved by Liaquat Ali Khan and passed on 12 March 1949.", "It later became the preamble and then Article 2A of the Constitution.", [3492]),
 (S, "What is the border agreement signed between China and Pakistan in 1963 known as?", ["Sino-Pakistan Boundary Agreement", "Karakoram Treaty", "Wakhan Agreement", "Durand Agreement"], 0,
  "On 2 March 1963 Pakistan and China signed the Sino-Pakistan Boundary Agreement fixing the border in the north.", "The Karakoram Highway linking the two countries was built later.", [2792]),
 (S, "What type of constitution did Pakistan have under the 1962 Constitution?", ["Parliamentary", "Presidential", "Monarchy", "Military council"], 1,
  "The 1962 Constitution, given by Ayub Khan, set up a presidential form of government with a strong President.", "It was Pakistan's second constitution and was abrogated in 1969.", [72]),
 (S, "On what date was the 1962 Constitution of Pakistan enforced?", ["8 June 1962", "1 March 1962", "23 March 1956", "25 March 1969"], 0,
  "The 1962 Constitution was announced on 1 March 1962 and came into force on 8 June 1962.", "It was abrogated on 25 March 1969 when Yahya Khan imposed martial law.", [2305]),
 (S, "In which year did Balochistan become a province of Pakistan?", ["1970", "1972", "1973", "1956"], 0,
  "When the One Unit scheme of West Pakistan was dissolved on 1 July 1970, Balochistan became a full province.", "Balochistan is the largest province of Pakistan by area.", [2121, 3375, 3376]),
 (S, "In which year was the present Constitution of Pakistan made?", ["1956", "1962", "1973", "1985"], 2,
  "The present Constitution was passed by the National Assembly in April 1973 and enforced on 14 August 1973.", "It was drafted under Prime Minister Zulfikar Ali Bhutto.", [2182]),
 (S, "In which year did the First World War start?", ["1914", "1916", "1918", "1939"], 0,
  "The First World War began in 1914 after the assassination of Archduke Franz Ferdinand.", "It ended in 1918.", [2141]),
]
